Item.method_code:
const currentTarget = options.currentTarget;
if (currentTarget.dashboard || !currentTarget.itemTypeId || currentTarget.locked) {
	return {
		hidden: true
	};
}

const {
	itemType,
	itemTypeName,
	location
} = options;
const openNewCommand = options.commandFactory('OpenNewItem', { itemType, itemTypeName, location });
const hidden = !openNewCommand.canExecute();
const itemTypeLabel = itemType.label || itemType.name;
const labelTemplate = target.labelTemplate || target.label;
return {
	hidden,
	label: labelTemplate.replace('{0}', itemTypeLabel),
	labelTemplate
};
